?DrawShootGridList@@YAXXZ PROC NEAR			; DrawShootGridList, COMDAT

; 45   : {

	push	ebp
	mov	ebp, esp

; 46   : #ifdef _DEBUG
; 47   : 	if ( vShootGridList.empty() )
; 48   : 		return;
; 49   : 	//Draw line
; 50   : 	stPointI lastGrid(0,0);
; 51   : 	stPointI ptGrid;
; 52   : 	std::vector<stPointI>::iterator itor;
; 53   : 
; 54   : 	for( itor=vShootGridList.begin();itor!=vShootGridList.end();itor++ )
; 55   : 	{
; 56   : 		ptGrid = *itor;
; 57   : 		stPointI ptStart;
; 58   : 		stPointI ptEnd;
; 59   : 		ptStart.x = lastGrid.x * GRID_WIDTH - GRID_WIDTH/2 + GetDevice()->GetWidth()/2;
; 60   : 		ptStart.y = lastGrid.y * GRID_HEIGHT - GRID_HEIGHT/2 + GetDevice()->GetHeight()/2;
; 61   : 		ptEnd.x = ptGrid.x * GRID_WIDTH - GRID_WIDTH/2 + GetDevice()->GetWidth()/2;
; 62   : 		ptEnd.y = ptGrid.y * GRID_HEIGHT - GRID_HEIGHT/2 + GetDevice()->GetHeight()/2;
; 63   : 		
; 64   : 		GetDevice()->DrawLine( &ptStart, &ptEnd,	D3DCOLOR_ARGB(255,255,0,0) );
; 65   : 
; 66   : 		lastGrid = ptGrid;
; 67   : 	}
; 68   : 	
; 69   : #endif
; 70   : }

	pop	ebp
	ret	0
